using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "SaviorPendantOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/SaviorPendant Omen Data")]
public class SaviorPendantOmenData : OnStartOfBattleOmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		omenAction = delegate
		{
			omenInstance.ActivateOmenFeedback();
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, 0.6f, delegate
			{
				ActivateOmen();
			});
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.SaviorPendantOmenAction = omenAction;
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.SaviorPendantOmenAction = null;
	}
}
